// md5_uint.cpp
// 简单的 MD5 实现（RFC1321），并提供 md5_to_uint(string) -> unsigned
// int（uint32_t）
// 版权：此实现参考公开域/教学实现，适合学习与工程使用。

#include <cstdint>
#include <cstring>
#include <iomanip>
#include <iostream>
#include <string>
#include <vector>

using uint32 = uint32_t;
using uint8 = uint8_t;

class MD5 {
public:
    MD5() {
        init();
    }

    void update(const uint8* input, size_t length) {
        size_t idx = (count[0] >> 3) & 0x3F;
        uint64_t bits = (uint64_t)length << 3;

        // update bit count
        count[0] += (uint32)bits;
        if (count[0] < (uint32)bits)
            count[1]++;
        count[1] += (uint32)(length >> 29);

        size_t partLen = 64 - idx;
        size_t i = 0;
        if (length >= partLen) {
            memcpy(&buffer[idx], input, partLen);
            transform(buffer);

            for (i = partLen; i + 63 < length; i += 64)
                transform(&input[i]);
            idx = 0;
        } else {
            i = 0;
        }
        memcpy(&buffer[idx], &input[i], length - i);
    }

    void finalize(uint8 digest[16]) {
        static const uint8 PADDING[64] = {0x80};
        uint8 bits[8];
        encodeBits(bits);

        size_t idx = (count[0] >> 3) & 0x3f;
        size_t padLen = (idx < 56) ? (56 - idx) : (120 - idx);
        update(PADDING, padLen);
        update(bits, 8);

        encodeState(digest);
        // clear sensitive data
        memset(buffer, 0, sizeof(buffer));
        count[0] = count[1] = 0;
    }

private:
    void init() {
        count[0] = count[1] = 0;
        // 消息摘要初始向量（RFC1321）
        state[0] = 0x67452301;
        state[1] = 0xEFCDAB89;
        state[2] = 0x98BADCFE;
        state[3] = 0x10325476;
