    static inline uint32 F(uint32 x, uint32 y, uint32 z) {
        return (x & y) | (~x & z);
    }
    static inline uint32 G(uint32 x, uint32 y, uint32 z) {
        return (x & z) | (y & ~z);
    }
    static inline uint32 H(uint32 x, uint32 y, uint32 z) {
