#### 背包问题

背包问题，有n个物品，不同物品不同重量且不同价值，指定某个容量下的最大价值配比。

```C++ 
int w[] = {12, 3, 8, 9, 6};   // 物品重量
int v[] = {9, 11, 4, 7, 8};   // 物品价值
const int len = sizeof(w) / sizeof(w[0]);
std::vector<int> sel;                         // 选择的物品
int c = 20;                                   // 背包容量
int r = std::accumulate(v, std::end(v), 0);   // 剩余总价值
int cw = 0;                                   // 已选择物品的重量
int cv = 0;                                   // 已选择物品的价值

unsigned int bestv = 0;

void func(int i) {
    // 背包问题，有n个物品，不同物品不同重量且不同价值，指定某个容量下的最大价值配比。
    if (i == len) {
        // 到达叶子节点
        if (cv > bestv) {
            bestv = cv;
            std::cout << "此时的价值为： " << bestv << std::endl;
            for (auto v : sel) {
                std::cout << v << " ";
            }
            std::cout << std::endl;
        }
    } else {
        // 左剪枝
        if (cw + w[i] <= c) {
            // 选择物品的重量加上即将处理的物品的重量小于背包容量才能选择
            cw += w[i];
            cv += v[i];
            sel.push_back(w[i]);
            func(i + 1);

            sel.pop_back();
            // 没有选择该物品
            cw -= w[i];
            cv -= v[i];
        }
        // 右剪枝
        if (cv + r > bestv) {
            // 只有剩余价值加上当前积累价值大于最大价值才值得继续遍历
            func(i + 1);
        }
    }
}
```

## 排列树

**从 n 个不同元素中，取出所有元素，按照顺序排列** 的一种树形表示方法。

每一条从 **根节点到叶子节点的路径**，对应一个排列。  

换句话说，排列树就是把所有 **全排列** 的生成过程，形象化为一棵树。

```
               (root)
           /     |     \
         1       2      3
       /  \     / \    /  \
      2    3   1  3   1   2
     /    /   /  /   /   /
    3    2  3   2   2   1

```

:::code-group
```C++ [排列树模板]
int vec[5] = {1 ,2 ,3 ,4 ,5};
int len = sizeof(vec) / sizeof(vec[0]);

void swap(int arr[], int i, int j) {
    int temp = arr[i];
    arr[i] = arr[j];
    arr[j] = temp;
}
void func(int arr[], int i) {
    if (i == len) {
        // 到达叶子节点
        for (auto v : vec) {
            std::cout << v << " ";
        }
        std::cout << std::endl;
    } else {
        for (int j = i; j < len; ++j) {
            swap(arr, i, j);
            func(arr, i + 1);
            swap(arr, i ,j);
        }
    }
}
```
:::

在代码中主要通过两个元素的交换，来实现不同的排列。

### N皇后问题

比较经典的就是8皇后问题：皇后会吃点她直线或斜线上的敌人。

现在棋盘上有8个皇后，要怎么摆才不能让互相她们吃掉。

:::code-group
```C++ [交换法排列树]
// 把ar数组的下标当作行，下标对应的元素的值当作列
int ar[] = {1, 2, 3, 4, 5, 6, 7, 8};
int len = sizeof(ar) / sizeof(ar[0]);
int n = 8;
void swap(int i, int j) {
    int temp = ar[i];
    ar[i] = ar[j];
    ar[j] = temp;
}

bool judge(int i) {
    // 当前的皇后和前面的皇后进行比较
    for (int j = 0; j < i; ++j) {
        // i == j：同行
        // ar[i] == ar[j]：同列
        // i - j == ar[i] - ar[j]：同斜线
        if (i == j || ar[i] == ar[j] ||
            std::abs(i - j) == std::abs(ar[i] - ar[j])) {
            return false;
        }
    }
    return true;
}

void func(int i) {
    // 8皇后
    if (i == len) {
        // 叶子节点
        for (auto v : ar) {
            std::cout << v << " ";
        }
        std::cout << std::endl;
    } else {
        for (int j = i; j < len; ++j) {
            swap(i, j);
            if (judge(i)) {
                func(i + 1);
            }
            swap(i, j);
        }
    }
}
```
```C++ [穷举法排列树]
std::vector<bool> state(len, false);
std::vector<int> vec;
bool judge(int i) {
    // 当前的皇后和前面的皇后进行比较
    for (int j = 0; j < i; ++j) {
        // i == j：同行
        // vec[i] == vec[j]：同列
        // i - j == vec[i] - vec[j]：同斜线
        if (i == j || vec[i] == vec[j] ||
            std::abs(i - j) == std::abs(vec[i] - vec[j])) {
            return false;
        }
    }
    return true;
}
void func(int i) {
    // 8皇后
    if (i == len) {
        // 叶子节点
        for (auto v : vec) {
            std::cout << v << " ";
        }
        std::cout << std::endl;

    } else {
        for (int j = 0; j < len; ++j) {
            if (!state[j]) {
                state[j] = true;
                vec.push_back(ar[j]);
                if (judge(i)) {
                    func(i + 1);
                }
                vec.pop_back();
                state[j] = false;
            }
        }
    }
}
```
